var ru=A.ui.rep={days:7};
function chart(rows){var W=800,Hh=230,pad=34,max=Math.max.apply(null,rows.map(function(r){return r.rev}))||1,n=rows.length;var x=function(i){return pad+(W-pad*2)*(n>1?i/(n-1):.5)},y=function(v){return Hh-pad-(Hh-pad*2)*v/max};
  var pts=rows.map(function(r,i){return [x(i),y(r.rev)]});var d=pts.map(function(p,i){return (i?'L':'M')+p[0].toFixed(1)+' '+p[1].toFixed(1)}).join(' ');var area=d+' L'+x(n-1)+' '+(Hh-pad)+' L'+x(0)+' '+(Hh-pad)+'Z';
  var grid=[0,.5,1].map(function(f){var yy=y(max*f);return '<line x1="'+pad+'" x2="'+(W-pad)+'" y1="'+yy+'" y2="'+yy+'" stroke="#F2DDC0" stroke-dasharray="6 6"/><text x="'+(pad-6)+'" y="'+(yy+4)+'" text-anchor="end" font-size="11" fill="#8B6A58" font-weight="700">'+TX.num(max*f/1000)+'k</text>'}).join('');
  var lab=rows.map(function(r,i){if(n>10&&i%Math.ceil(n/8)&&i!==n-1)return '';var dd=new Date(r.t);return '<text x="'+x(i)+'" y="'+(Hh-10)+'" text-anchor="middle" font-size="11" fill="#8B6A58" font-weight="700">'+(dd.getMonth()+1)+'/'+dd.getDate()+'</text>'}).join('');
  return '<svg class="chart" viewBox="0 0 '+W+' '+Hh+'" role="img" aria-label="每日營收折線圖">'+grid+'<path d="'+area+'" fill="var(--acc)" opacity=".22"/><path d="'+d+'" fill="none" stroke="var(--acc-d)" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>'+pts.map(function(p,i){return '<circle cx="'+p[0]+'" cy="'+p[1]+'" r="5" fill="#fff" stroke="var(--acc-d)" stroke-width="3"><title>'+TX.fmtDay(rows[i].t)+'：'+TX.money(rows[i].rev)+'</title></circle>'}).join('')+lab+'</svg>'}
function barRows(list,key){var mx=Math.max.apply(null,list.map(function(x){return x.v}))||1;return list.map(function(x){return '<div class="hb"><span>'+h(x.k)+'</span><div class="tr"><i style="--w:'+Math.round(x.v/mx*100)+'%"></i></div><span class="v">'+(key==='pct'?(x.pct||x.v)+'%':TX.num(x.v))+'</span></div>'}).join('')}
